package com.codereviewer.utils;

import com.codereviewer.model.codeIssue;

import java.util.List;

public final class PromptBuilder {

    private PromptBuilder() {
    }

    /**
     * Builds an expert prompt for the AI code reviewer.
     *
     * @param sourceCode   Java source code being reviewed
     * @param staticIssues findings generated by static analyzers
     * @return complete AI review prompt
     */
    public static String build(
            String sourceCode,
            List<codeIssue> staticIssues) {

        StringBuilder prompt = new StringBuilder();

        prompt.append("You are a Principal Software Engineer and Application Security Architect.\n");
        prompt.append("Conduct a rigorous code review of the provided Java source code.\n");
        prompt.append("Evaluate security vulnerabilities (OWASP Top 10), concurrency race conditions, ");
        prompt.append("resource/stream leaks, unhandled exceptions, and algorithmic efficiency.\n\n");
        prompt.append("GUIDELINES:\n");
        prompt.append("- Be concise, objective, and actionable. Do not hallucinate false issues.\n");
        prompt.append("- Ground your review on actual code semantics. Cross-check the static analysis findings below.\n");
        prompt.append("- For every issue, specify the line number or code snippet, impact, and exact fix.\n\n");

        prompt.append("STATIC ANALYSIS AST FINDINGS:\n");
        if (staticIssues == null || staticIssues.isEmpty()) {
            prompt.append("No static AST violations detected.\n");
        } else {
            for (codeIssue issue : staticIssues) {
                prompt.append("- [")
                        .append(issue.getSeverity())
                        .append("] ")
                        .append(issue.getRule())
                        .append(" (line ")
                        .append(issue.getLine())
                        .append("): ")
                        .append(issue.getMessage())
                        .append("\n");
            }
        }

        prompt.append("\nJAVA SOURCE CODE TO REVIEW:\n```java\n");
        prompt.append(sourceCode);
        prompt.append("\n```\n\n");

        prompt.append("OUTPUT FORMAT:\n");
        prompt.append("### 1. Executive Summary & Code Quality Score (0 - 10)\n");
        prompt.append("### 2. Critical Security & Logic Vulnerabilities\n");
        prompt.append("### 3. Performance, Memory & Resource Safety\n");
        prompt.append("### 4. Production-Ready Refactored Code Fix (complete replacement block)\n");

        return prompt.toString();
    }
}